int check_link_filtered(const char *ground_station) {
    if (ground_station == nullptr) return -1;
    for (const char *p = ground_station; *p; p++) {
        bool ok = (*p >= 'a' && *p <= 'z') || (*p >= 'A' && *p <= 'Z') ||
                  (*p >= '0' && *p <= '9') || *p == '.' || *p == '-';
        if (!ok) return -1;
    }
    pid_t pid = fork();
    if (pid == 0) {
        execl("/bin/ping", "ping", "-c", "1", ground_station, (char *)nullptr);
        _exit(127);
    }
    if (pid < 0) return -1;
    int status = 0;
    waitpid(pid, &status, 0);
    return status;
}

